{ "Mass loss from post-main-sequence stars supplies much of the heavy-element and solid content of the ISM.": "provides a large fraction of the heavy element abundance and solid particle content of the interstellar medium" },
 { "AGB mass loss is thought to involve radiation pressure and pulsation, but its details are poorly understood.": "are thought to involve both radiation pressure and stellar pulsation" },
 { "Molecular line and deep imaging studies reveal periodic mass-loss variations producing 'rings' in envelopes.": "found strong evidence for periodic variations in mass-loss rates leading to the appearance of 'rings'" },
 { "Inner circumstellar structure requires angular resolutions well under 1 arcsec.": "angular resolutions well under 1 arcsec are required" },
 { "Most prior interferometric work used only one or two broad bands, limiting structural diagnostics.": "most interferometric observations have been made in typically one or two relatively broad bands" },
 { "Lunar occultations and multi-aperture interferometry reach milli-arcsecond resolution.": "have pushed angular resolutions to the milli-arcsecond level" },
 { "Studying the inner dust shell requires resolving the warmest dust emission alongside the stellar fringe pattern.": "observe simultaneously the Fresnel fringe pattern of the obscured central star ... together with the circumstellar dust emission" }
],
"research_question_and_hypothesis": [
 { "Can high-resolution, broad-wavelength occultation data resolve the inner dust shell of AFGL 5440?": "Resolving The Dust Shell Around AFGL 5440" },
 { "Do the occultation fringes require a single source size, or do they imply a structured star+shell?": "a single source size was unlikely to fit over the entire 1 – 4µm bandwidth" },
 { "Can a single-size uniform disk reproduce the full-wavelength occultation light curves?": "the 11 mas disk provides a passable fit in the mid-range of wavelengths, 2.5 – 3.2µm, but produces fringes that are too sharp at the longer wavelengths and too broadened at the shortest wavelengths" },
 { "Does a full radiative-transfer model fit both the occultation fringes and the SED?": "We use the DUSTY radiative transfer code to model a circumstellar shell and fit both the observed occultation light curves and the spectral energy distribution" },
 { "Is the inner dust-shell temperature constrained to ~950 K?": "Tmax = 950 K ± 50K" },
 { "Is the density gradient consistent with a radiatively driven outflow (ρ ∝ r−2)?": "a density gradient of ρ ∝r−2 or the gradient derived by Ivezi´c & Elitzur for a radiatively driven hydrodynamic outﬂow" },
 { "Can the IRAS 60µm flux be fit without graphite or a higher past mass-loss rate?": "Our models cannot fit the observed IRAS 60µm flux without assuming a substantial abundance of graphite or by assuming a substantially higher mass-loss rate in the past" }
],
"methodological_details": [
 { "The target is the carbon-rich AGB star AFGL 5440 (aka OH 06.86-1.5, IRAS 18036-2344).": "lunar occultation of the star AFGL 5440 (aka OH 06.86-1.5, IRAS 18036-2344)" },
 { "The distance is estimated at 2.25 kpc, implying a luminosity of 1.4×10^4 L⊙.": "Groenewegen et al. (2002) have estimated the distance to be 2.25 kpc" },
 { "The occultation was an immersion event on 28 Aug 2001 at ~02:44:00 UT.": "made during an immersion occultation event on 28 Aug 2001 at approximately 02:44:00 UT" },
 { "Observing geometry: Moon elevation 36°, Sun 17° below horizon, position angle 54°, lunar phase 0.72.": "The elevation of the Moon at the time of the event was 36◦, and the Sun was 17◦below the horizon. The position angle of the occultation event on the lunar limb was 54◦, and the lunar phase was 0.72." },
 { "Observations used the pMIRAS instrument on the McDonald Observatory 2.7-m telescope.": "We used the pMIRAS instrument on the McDonald Observatory 2.7-m telescope." },
 { "The instrument is a long/wide-slit, high-speed spectrophotometer using a NaCl prism dispersing light onto a 32×100 pixel region of a 256² InSb array.": "using a NaCl prism to disperse the light from the slit, which is then imaged onto a 32×100 pixel portion of a 2562 InSb array detector" },
 { "The slit width was set at ~5 arcsec for typical seeing of 1.5 arcsec.": "For these observations the slit width was set at about 5 arcsec for the typical seeing of 1.5 arcsec." },
 { "The detector is read out every 8 msec, with photon integration over essentially the full 8 msec.": "The detector is read-out every 8 msec, with photon integration occuring over essentially the full 8 msec time." },
